import React, { Component } from "react";
import {
  BrowserRouter as Router,
  Link,
  Route,
  Redirect,
} from "react-router-dom";
import { Layout, Menu, Icon, Button, Modal, Input, Alert, Avatar } from "antd";

import Dashboard from "./Dashboard";
import Profile from "./Profile";
import Streams from "./Streams";
import Live from "./Live";
import VOD from "./VOD";
import API_BASE_URL from "./config";

import "./App.css";

const { Header, Sider, Content, Footer } = Layout;

const ADMIN_CHECK_API = `${API_BASE_URL}/api/server`;
const STORAGE_KEY = "nms_admin_auth";

class App extends Component {
  state = {
    collapsed: false,
    isAuthenticated: false,
    authHeader: null,
    username: "",

    loginModalVisible: false,
    loginLoading: false,
    loginUsername: "",
    loginPassword: "",
    loginError: null,
  };

  componentDidMount() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);

      if (raw) {
        const parsed = JSON.parse(raw);

        if (parsed && parsed.username && parsed.authHeader) {
          this.setState({
            isAuthenticated: true,
            username: parsed.username,
            authHeader: parsed.authHeader,
          });
        }
      }
    } catch (error) {
      localStorage.removeItem(STORAGE_KEY);
    }
  }

  toggle = () => {
    this.setState({
      collapsed: !this.state.collapsed,
    });
  };

  getFullTitle = () => {
    return this.state.isAuthenticated ? "NMS Admin" : "NMS Viewer";
  };

  getShortTitle = () => {
    return this.state.isAuthenticated ? "ADMIN" : "NMS";
  };

  openLoginModal = () => {
    this.setState({
      loginModalVisible: true,
      loginError: null,
      loginPassword: "",
    });
  };

  closeLoginModal = () => {
    this.setState({
      loginModalVisible: false,
      loginLoading: false,
      loginError: null,
      loginPassword: "",
    });
  };

  handleLoginUsernameChange = (event) => {
    this.setState({ loginUsername: event.target.value });
  };

  handleLoginPasswordChange = (event) => {
    this.setState({ loginPassword: event.target.value });
  };

  handleLogin = async () => {
    const { loginUsername, loginPassword } = this.state;

    if (!loginUsername.trim() || !loginPassword.trim()) {
      this.setState({
        loginError: "Debes introducir usuario y contraseña",
      });
      return;
    }

    this.setState({
      loginLoading: true,
      loginError: null,
    });

    try {
      const authHeader = `Basic ${btoa(
        `${loginUsername.trim()}:${loginPassword}`,
      )}`;

      const response = await fetch(ADMIN_CHECK_API, {
        headers: {
          Authorization: authHeader,
        },
      });

      if (!response.ok) {
        throw new Error("Credenciales incorrectas");
      }

      const authData = {
        username: loginUsername.trim(),
        authHeader: authHeader,
      };

      localStorage.setItem(STORAGE_KEY, JSON.stringify(authData));

      this.setState({
        isAuthenticated: true,
        username: loginUsername.trim(),
        authHeader: authHeader,
        loginModalVisible: false,
        loginLoading: false,
        loginError: null,
        loginPassword: "",
      });
    } catch (error) {
      this.setState({
        loginLoading: false,
        loginError: error.message || "No se pudo iniciar sesión",
      });
    }
  };

  handleLogout = () => {
    localStorage.removeItem(STORAGE_KEY);

    this.setState({
      isAuthenticated: false,
      username: "",
      authHeader: null,
      loginUsername: "",
      loginPassword: "",
      loginError: null,
      loginModalVisible: false,
      loginLoading: false,
    });
  };

  getMenuItems = () => {
    const publicItems = [
      {
        key: "/live",
        label: "Live",
        icon: "play-circle",
      },
      {
        key: "/vod",
        label: "VOD",
        icon: "video-camera",
      },
    ];

    const adminItems = [
      {
        key: "/dashboard",
        label: "Dashboard",
        icon: "dashboard",
      },
      {
        key: "/streams",
        label: "Streams",
        icon: "database",
      },
      {
        key: "/profile",
        label: "Profile",
        icon: "profile",
      },
    ];

    if (this.state.isAuthenticated) {
      return publicItems.concat(adminItems);
    }

    return publicItems;
  };

  getSelectedMenuKey = (pathname) => {
    if (pathname === "/") return "/live";
    if (pathname.indexOf("/live") === 0) return "/live";
    if (pathname.indexOf("/vod") === 0) return "/vod";
    if (pathname.indexOf("/dashboard") === 0) return "/dashboard";
    if (pathname.indexOf("/streams") === 0) return "/streams";
    if (pathname.indexOf("/profile") === 0) return "/profile";

    if (pathname.indexOf("/admin/streams") === 0) return "/streams";
    if (pathname.indexOf("/admin/profile") === 0) return "/profile";
    if (pathname.indexOf("/admin") === 0) return "/dashboard";

    return "/live";
  };

  renderHeaderRight = () => {
    const { isAuthenticated, username } = this.state;

    if (isAuthenticated) {
      return (
        <div style={{ display: "flex", alignItems: "center", gap: 12 }}>
          <div
            style={{
              display: "flex",
              alignItems: "center",
              color: "#262626",
              fontWeight: 500,
            }}
          >
            <Avatar
              size="small"
              icon="user"
              style={{ marginRight: 8, backgroundColor: "#1890ff" }}
            />
            {username}
          </div>

          <Button icon="logout" onClick={this.handleLogout}>
            Cerrar sesión
          </Button>
        </div>
      );
    }

    return (
      <Button icon="user" onClick={this.openLoginModal}>
        Iniciar sesión
      </Button>
    );
  };

  renderProtectedRoute = (ComponentToRender, routeProps) => {
    if (!this.state.isAuthenticated) {
      return <Redirect to="/live" />;
    }

    return (
      <ComponentToRender
        {...routeProps}
        authHeader={this.state.authHeader}
        isAuthenticated={this.state.isAuthenticated}
      />
    );
  };

  render() {
    const {
      collapsed,
      isAuthenticated,
      authHeader,
      loginModalVisible,
      loginLoading,
      loginUsername,
      loginPassword,
      loginError,
    } = this.state;

    const title = collapsed ? this.getShortTitle() : this.getFullTitle();

    return (
      <Router>
        <Route
          render={({ location }) => (
            <Layout style={{ minHeight: "100vh" }}>
              <Sider
                width={256}
                trigger={null}
                collapsible
                collapsed={collapsed}
              >
                <div
                  className="logo"
                  style={{
                    height: 64,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: collapsed ? "center" : "flex-start",
                    padding: collapsed ? 0 : "0 20px",
                    color: "#fff",
                    fontSize: collapsed ? 16 : 22,
                    fontWeight: 700,
                    borderBottom: "1px solid rgba(255,255,255,0.08)",
                  }}
                >
                  {title}
                </div>

                <Menu
                  theme="dark"
                  mode="inline"
                  selectedKeys={[this.getSelectedMenuKey(location.pathname)]}
                >
                  {this.getMenuItems().map((item) => (
                    <Menu.Item key={item.key}>
                      <Link to={item.key}>
                        <Icon type={item.icon} />
                        <span>{item.label}</span>
                      </Link>
                    </Menu.Item>
                  ))}
                </Menu>
              </Sider>

              <Layout>
                <Header
                  style={{
                    background: "#fff",
                    padding: "0 20px",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "space-between",
                    boxShadow: "0 1px 4px rgba(0,0,0,0.08)",
                  }}
                >
                  <Icon
                    className="trigger"
                    type={collapsed ? "menu-unfold" : "menu-fold"}
                    onClick={this.toggle}
                    style={{ fontSize: 18, cursor: "pointer" }}
                  />

                  {this.renderHeaderRight()}
                </Header>

                <Content
                  style={{
                    margin: "24px 16px",
                    minHeight: 280,
                  }}
                >
                  <Route
                    exact
                    path="/"
                    render={() => <Redirect to="/live" />}
                  />

                  <Route
                    exact
                    path="/live"
                    render={(props) => (
                      <Live
                        {...props}
                        isAuthenticated={isAuthenticated}
                        authHeader={authHeader}
                      />
                    )}
                  />

                  <Route
                    exact
                    path="/vod"
                    render={(props) => (
                      <VOD
                        {...props}
                        isAuthenticated={isAuthenticated}
                        authHeader={authHeader}
                      />
                    )}
                  />

                  <Route
                    exact
                    path="/dashboard"
                    render={(props) =>
                      this.renderProtectedRoute(Dashboard, props)
                    }
                  />
                  <Route
                    exact
                    path="/streams"
                    render={(props) =>
                      this.renderProtectedRoute(Streams, props)
                    }
                  />
                  <Route
                    exact
                    path="/profile"
                    render={(props) =>
                      this.renderProtectedRoute(Profile, props)
                    }
                  />

                  <Route
                    exact
                    path="/admin"
                    render={() => <Redirect to="/dashboard" />}
                  />
                  <Route
                    exact
                    path="/admin/streams"
                    render={() => <Redirect to="/streams" />}
                  />
                  <Route
                    exact
                    path="/admin/profile"
                    render={() => <Redirect to="/profile" />}
                  />
                </Content>

                <Footer style={{ textAlign: "center" }}>
                  Node-Media-Server ©2019 Created by{" "}
                  <a
                    href="http://nodemedia.cn"
                    rel="noopener noreferrer"
                    target="_blank"
                  >
                    NodeMedia
                  </a>
                </Footer>
              </Layout>

              <Modal
                title="Iniciar sesión como administrador"
                visible={loginModalVisible}
                onCancel={this.closeLoginModal}
                onOk={this.handleLogin}
                confirmLoading={loginLoading}
                okText="Entrar"
                cancelText="Cancelar"
                destroyOnClose
              >
                {loginError ? (
                  <Alert
                    type="error"
                    message={loginError}
                    showIcon
                    style={{ marginBottom: 16 }}
                  />
                ) : null}

                <div style={{ marginBottom: 16 }}>
                  <div
                    style={{
                      marginBottom: 6,
                      fontWeight: 600,
                      color: "#262626",
                    }}
                  >
                    Usuario
                  </div>
                  <Input
                    value={loginUsername}
                    onChange={this.handleLoginUsernameChange}
                    placeholder="Introduce el usuario"
                    size="large"
                  />
                </div>

                <div>
                  <div
                    style={{
                      marginBottom: 6,
                      fontWeight: 600,
                      color: "#262626",
                    }}
                  >
                    Contraseña
                  </div>
                  <Input
                    type="password"
                    value={loginPassword}
                    onChange={this.handleLoginPasswordChange}
                    placeholder="Introduce la contraseña"
                    size="large"
                    onPressEnter={this.handleLogin}
                  />
                </div>
              </Modal>
            </Layout>
          )}
        />
      </Router>
    );
  }
}

export default App;
