import React, { Component } from "react";
import {
  Card,
  Col,
  Row,
  Tag,
  Empty,
  Spin,
  Alert,
  Button,
  Modal,
  Form,
  Input,
  List,
  message,
} from "antd";
import VideoPlayer from "./VideoPlayer";

import API_BASE_URL from "./config";

// Público
const PUBLIC_STREAMS_API = `${API_BASE_URL}/public-api/streams`;

// Privado
const PREPARE_API = `${API_BASE_URL}/api/videos`;

class Live extends Component {
  state = {
    streams: [],
    loading: true,
    error: null,
    selectedStreamKey: null,

    prepareModalVisible: false,
    prepareTitle: "",
    prepareStreamKey: "",
    prepareLoading: false,
    prepareError: null,
  };

  componentDidMount() {
    this.fetchStreams();
    this.interval = setInterval(this.fetchStreams, 10000);
  }

  componentWillUnmount() {
    clearInterval(this.interval);
  }

  fetchStreams = async () => {
    try {
      const res = await fetch(PUBLIC_STREAMS_API);

      if (!res.ok) throw new Error(`HTTP ${res.status}`);

      const data = await res.json();
      const liveApp = data.live || {};

      const streams = Object.entries(liveApp).map(([key, info]) => ({
        key: key,
        hlsUrl: `${API_BASE_URL}/live/${key}/hls/master.m3u8`,
        subscribers: info.subscribers ? info.subscribers.length : 0,
      }));

      let selectedStreamKey = this.state.selectedStreamKey;

      if (!selectedStreamKey && streams.length > 0) {
        selectedStreamKey = streams[0].key;
      }

      if (
        selectedStreamKey &&
        streams.findIndex((stream) => stream.key === selectedStreamKey) === -1
      ) {
        selectedStreamKey = streams.length > 0 ? streams[0].key : null;
      }

      this.setState({
        streams: streams,
        loading: false,
        error: null,
        selectedStreamKey: selectedStreamKey,
      });
    } catch (err) {
      this.setState({
        loading: false,
        error: err.message,
      });
    }
  };

  selectStream = (streamKey) => {
    this.setState({ selectedStreamKey: streamKey });
  };

  openPrepareModal = () => {
    if (!this.props.isAuthenticated) {
      return;
    }

    this.setState({
      prepareModalVisible: true,
      prepareError: null,
    });
  };

  closePrepareModal = () => {
    this.setState({
      prepareModalVisible: false,
      prepareTitle: "",
      prepareStreamKey: "",
      prepareLoading: false,
      prepareError: null,
    });
  };

  handlePrepareTitleChange = (event) => {
    this.setState({ prepareTitle: event.target.value });
  };

  handlePrepareStreamKeyChange = (event) => {
    this.setState({ prepareStreamKey: event.target.value });
  };

  handlePrepareSubmit = async () => {
    const { prepareTitle, prepareStreamKey } = this.state;
    const { authHeader, isAuthenticated } = this.props;

    if (!isAuthenticated || !authHeader) {
      this.setState({
        prepareError: "Debes iniciar sesión como administrador",
      });
      return;
    }

    if (!prepareTitle.trim() || !prepareStreamKey.trim()) {
      this.setState({
        prepareError: "Debes rellenar el título y la stream key",
      });
      return;
    }

    this.setState({
      prepareLoading: true,
      prepareError: null,
    });

    try {
      const res = await fetch(PREPARE_API, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: authHeader,
        },
        body: JSON.stringify({
          title: prepareTitle.trim(),
          stream_key: prepareStreamKey.trim(),
        }),
      });

      const data = await res.json().catch(function() {
        return null;
      });

      if (!res.ok) {
        throw new Error(data && data.error ? data.error : `HTTP ${res.status}`);
      }

      message.success("Emisión preparada correctamente");
      this.closePrepareModal();
    } catch (err) {
      this.setState({
        prepareLoading: false,
        prepareError: err.message,
      });
    }
  };

  renderActiveStreamItem = (stream, selectedStreamKey) => {
    const isSelected = selectedStreamKey === stream.key;

    return (
      <List.Item
        onClick={() => this.selectStream(stream.key)}
        style={{
          padding: "16px 18px",
          cursor: "pointer",
          background: isSelected ? "#f0f7ff" : "#fff",
          borderLeft: isSelected
            ? "4px solid #1890ff"
            : "4px solid transparent",
        }}
      >
        <div style={{ width: "100%" }}>
          <div
            style={{
              display: "flex",
              justifyContent: "space-between",
              alignItems: "center",
              gap: 12,
              marginBottom: 6,
            }}
          >
            <div
              style={{
                fontSize: 16,
                fontWeight: 700,
                color: "#1f1f1f",
              }}
            >
              {stream.key}
            </div>

            <Tag
              color="red"
              style={{
                borderRadius: 999,
                marginRight: 0,
              }}
            >
              LIVE
            </Tag>
          </div>

          <div style={{ color: "#8c8c8c", marginBottom: 10 }}>
            {stream.subscribers} espectador(es)
          </div>

          <Button
            size="small"
            icon="play-circle"
            onClick={(e) => {
              e.stopPropagation();
              this.selectStream(stream.key);
            }}
          >
            Ver en grande
          </Button>
        </div>
      </List.Item>
    );
  };

  render() {
    const { isAuthenticated } = this.props;
    const {
      streams,
      loading,
      error,
      selectedStreamKey,
      prepareModalVisible,
      prepareTitle,
      prepareStreamKey,
      prepareLoading,
      prepareError,
    } = this.state;

    const selectedStream =
      streams.find((stream) => stream.key === selectedStreamKey) || null;

    if (loading) {
      return <Spin size="large" style={{ display: "block", marginTop: 80 }} />;
    }

    if (error) {
      return (
        <Alert
          type="error"
          message={`Error al cargar streams: ${error}`}
          style={{ margin: 24 }}
        />
      );
    }

    return (
      <div
        style={{
          padding: "24px 24px 36px",
          maxWidth: 1500,
          margin: "0 auto",
        }}
      >
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            flexWrap: "wrap",
            gap: 16,
            marginBottom: 24,
          }}
        >
          <div>
            <h2
              style={{
                margin: 0,
                fontSize: 32,
                fontWeight: 700,
                color: "#1f1f1f",
              }}
            >
              Streams en Vivo
            </h2>

            <div style={{ color: "#8c8c8c", marginTop: 8 }}>
              Visualiza el directo principal y cambia entre emisiones activas
            </div>
          </div>

          {isAuthenticated ? (
            <Button
              type="primary"
              icon="form"
              size="large"
              onClick={this.openPrepareModal}
              style={{
                borderRadius: 10,
                fontWeight: 600,
              }}
            >
              Preparar emisión
            </Button>
          ) : null}
        </div>

        {streams.length === 0 ? (
          <Card
            bodyStyle={{ padding: 40 }}
            style={{
              borderRadius: 16,
              border: "1px solid #ececec",
            }}
          >
            <Empty description="No hay ningún stream activo ahora mismo" />
          </Card>
        ) : (
          <Row gutter={[32, 24]}>
            <Col xs={24} xl={16}>
              <div style={{ paddingRight: 8 }}>
                <Card
                  bodyStyle={{ padding: 18 }}
                  style={{
                    borderRadius: 18,
                    border: "1px solid #ececec",
                    boxShadow: "0 8px 24px rgba(0,0,0,0.04)",
                  }}
                >
                  <div
                    style={{
                      display: "flex",
                      justifyContent: "space-between",
                      alignItems: "center",
                      flexWrap: "wrap",
                      gap: 12,
                      marginBottom: 16,
                    }}
                  >
                    <div>
                      <div
                        style={{
                          fontSize: 24,
                          fontWeight: 700,
                          color: "#1f1f1f",
                          marginBottom: 6,
                        }}
                      >
                        {selectedStream ? selectedStream.key : "Directo"}
                      </div>

                      <div style={{ color: "#8c8c8c" }}>
                        Reproductor principal del stream seleccionado
                      </div>
                    </div>

                    <div>
                      <Tag
                        color="red"
                        style={{
                          borderRadius: 999,
                          padding: "4px 12px",
                          fontWeight: 600,
                          marginRight: 8,
                        }}
                      >
                        ● LIVE
                      </Tag>

                      <Tag
                        color="blue"
                        style={{
                          borderRadius: 999,
                          padding: "4px 12px",
                          fontWeight: 600,
                          marginRight: 0,
                        }}
                      >
                        {selectedStream ? selectedStream.subscribers : 0}{" "}
                        espectadores
                      </Tag>
                    </div>
                  </div>

                  <div
                    style={{
                      borderRadius: 14,
                      overflow: "hidden",
                      background: "#000",
                    }}
                  >
                    {selectedStream ? (
                      <VideoPlayer
                        src={selectedStream.hlsUrl}
                        autoPlay
                        showQualitySelector={false}
                        style={{
                          width: "100%",
                          minHeight: 520,
                          background: "#000",
                        }}
                      />
                    ) : null}
                  </div>
                </Card>
              </div>
            </Col>

            <Col xs={24} xl={8}>
              <div style={{ paddingLeft: 8 }}>
                <Card
                  title="Emisiones activas"
                  bodyStyle={{ padding: 0 }}
                  style={{
                    borderRadius: 18,
                    border: "1px solid #ececec",
                    boxShadow: "0 8px 24px rgba(0,0,0,0.04)",
                    overflow: "hidden",
                  }}
                >
                  <List
                    dataSource={streams}
                    renderItem={(stream) =>
                      this.renderActiveStreamItem(stream, selectedStreamKey)
                    }
                  />
                </Card>
              </div>
            </Col>
          </Row>
        )}

        <Modal
          title="Preparar emisión"
          visible={prepareModalVisible}
          onCancel={this.closePrepareModal}
          onOk={this.handlePrepareSubmit}
          confirmLoading={prepareLoading}
          okText="Guardar"
          cancelText="Cancelar"
          destroyOnClose
        >
          {prepareError ? (
            <Alert
              type="error"
              message={prepareError}
              showIcon
              style={{ marginBottom: 16 }}
            />
          ) : null}

          <Form layout="vertical">
            <Form.Item label="Título">
              <Input
                value={prepareTitle}
                onChange={this.handlePrepareTitleChange}
                placeholder="Ej. Evento presentación abril"
                size="large"
              />
            </Form.Item>

            <Form.Item label="Stream key">
              <Input
                value={prepareStreamKey}
                onChange={this.handlePrepareStreamKeyChange}
                placeholder="Ej. stream-evento-abril"
                size="large"
              />
            </Form.Item>

            <div
              style={{
                background: "#fafafa",
                border: "1px solid #f0f0f0",
                borderRadius: 12,
                padding: 16,
                color: "#595959",
                lineHeight: 1.7,
              }}
            >
              1. Guarda la emisión pendiente. <br />
              2. Emite desde OBS o Larix con esa misma stream key. <br />
              3. El backend enlazará esa emisión preparada con el directo real.
            </div>
          </Form>
        </Modal>
      </div>
    );
  }
}

export default Live;
